using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckSumo {
public enum SumoStage{Countdown,Fight,Replay,HeatResult}
public sealed class SumoMatch:SportsEventSession {
 public SumoFighter[] fighters;public Transform ring;public SportsEventCamera broadcast;public SportsMotionReplay replay;public SportsCameraFit fit;public float initialRadius=12,minimumRadius=5,shrinkBegins=23,shrinkSpeed=.16f,maximumHeat=90;public SumoRules rules=new SumoRules();public SumoStage Stage{get;private set;}public float Clock{get;private set;}public float Radius{get;private set;}public float Timer{get;private set;}public int HeatDraws{get;private set;}public int Impacts{get;private set;}public int ShrinkFrames{get;private set;}
 readonly float[] stuck=new float[4],reverse=new float[4],think=new float[4];readonly Vector2[] ai=new Vector2[4];readonly bool[] aiShove=new bool[4];readonly float[] soundCooldown=new float[4];readonly StringBuilder text=new StringBuilder(500),awards=new StringBuilder(300);readonly SumoAttribution attribution=new SumoAttribution();string notice="",awardNotice="";float awardUntil;public int QualifyingContacts{get;private set;}public int LastImpactVictim{get;private set;}=-1;public int LastImpactAttacker{get;private set;}=-1;public Vector3 LastReceivingNormal{get;private set;}public float LastContactSpeed{get;private set;}
 public override string Title=>"TRUCK SUMO";public override int MinimumPlayers=>2;public override int MaximumPlayers=>4;public override int OptionCount=>1;public override int WeatherCount=>1;public override string OptionLabel=>"FIRST TO FIVE HEATS";public override bool ReplayControls=>Stage==SumoStage.Replay;
 public override string Help=>"Drive and shove opponents out of the raised circular ring. First to five heat wins takes the match. Each credited opponent ring-out awards +1 activity point; the sole survivor earns +3 more. Points, ring-outs and heat wins are shown separately. Final ring-outs in one physics step give no survival bonus, but legitimate mutual ring-out points remain. Only meaningful recent physical pushes count; recovered, old or self-inflicted falls do not. The match still ends at five heat wins. Your authoritative chassis center must cross the visible outer edge: wheel overhang and being airborne inside do not eliminate you. Accelerate, steer, and brake before reversing. Press your assigned ACTION for one forward shove, then wait3.2seconds. A missed shove can carry you over the edge. Stopped trucks can be pushed; there is no stationary counter. At20seconds a warning announces the physical ring shrinking from23seconds toward its minimum. The visible surface and legal radius shrink together. An unresolved90second heat is an explicit draw and replay. Starts rotate each heat. Outfits and eyebrows are cosmetic. Recorded decisive replays offer angle, speed, rewind and skip. Pause/reconnect preserves the match; release and freshly confirm after replacement. No online services.";
 public override string Header=>Title+" · HEAT "+rules.Heat+" · "+(Stage==SumoStage.Countdown?Mathf.CeilToInt(Timer).ToString():Stage==SumoStage.Replay?"ACTUAL REPLAY":Clock.ToString("F1")+"s");
 public override string Status=>Stage==SumoStage.Fight&&Clock<awardUntil?awardNotice:Stage==SumoStage.Fight?(Clock>=20?(Clock<shrinkBegins?"THE RING SHRINKS IN "+Mathf.CeilToInt(shrinkBegins-Clock):"RING SHRINKING · WATCH THE EDGE"):"ACTION: SHOVE · THE CHASSIS CENTER DEFINES RING-OUT"):notice;
 public override string Standings=>BuildStandings(false);
 string BuildStandings(bool detailed){text.Clear();for(int i=0;i<setup.count;i++){text.Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[i].color)).Append('>').Append(setup.players[i].name).Append("</color>  ").Append(rules.points[i]).Append(detailed?" PTS · ":"P · ").Append(rules.ringouts[i]).Append(detailed?" RING-OUTS · ":"RO · ").Append(rules.wins[i]).Append(detailed?" / 5 WINS · ":"/5W · ").Append(!rules.alive[i]?"OUT":fighters[i].cooldown>0?(detailed?"SHOVE ":"")+fighters[i].cooldown.ToString("F1")+"s":"READY").Append('\n');}return text.ToString();}
 public override string Results=>(rules.Winner>=0?setup.players[rules.Winner].name+" IS THE SUMO CHAMPION":"MATCH COMPLETE")+"\n\n"+BuildStandings(true)+"\nDrawn heats: "+HeatDraws;
 public override bool TryReadScoreCard(int card,out string value,out string detail){if(card<0||card>=setup.count){value=detail=null;return false;}value=rules.points[card].ToString();detail=rules.ringouts[card]+" OUT · "+rules.wins[card]+"/5 W · "+(!rules.alive[card]?"OUT":fighters[card].cooldown>0?fighters[card].cooldown.ToString("F1")+"s":"READY");return true;}
 protected override void BeginGame(){rules.Reset(setup.count);HeatDraws=Impacts=ShrinkFrames=QualifyingContacts=0;replay.Colorize(Array.ConvertAll(setup.players,p=>p.color));BeginHeat();}
 void BeginHeat(){attribution.Reset(setup.count,rules.Heat);awardUntil=0;awardNotice="";Clock=0;Radius=initialRadius;Timer=2.5f;Stage=SumoStage.Countdown;notice="PREPARE TO SHOVE";ring.gameObject.SetActive(true);ring.localScale=new Vector3(Radius,1,Radius);replay.End();for(int i=0;i<4;i++){fighters[i].gameObject.SetActive(i<setup.count);if(i>=setup.count)continue;float angle=(i/(float)setup.count+(rules.Heat-1)*.137f)*Mathf.PI*2;var position=new Vector3(Mathf.Sin(angle),0,Mathf.Cos(angle))*(Radius-4);position.y=.7f;fighters[i].ResetFighter(position,Quaternion.LookRotation(new Vector3(-position.x,0,-position.z)));fighters[i].truck.TickDrive(Vector2.zero);stuck[i]=reverse[i]=think[i]=soundCooldown[i]=0;ai[i]=Vector2.zero;}replay.ResetRecord();}
 protected override void Simulate(float dt){if(Stage==SumoStage.Countdown){foreach(var fighter in fighters)if(fighter.gameObject.activeSelf)fighter.truck.TickDrive(Vector2.zero);Timer-=dt;if(Timer<=0){Stage=SumoStage.Fight;notice="SHOVE!";}return;}
  if(Stage==SumoStage.Replay){if(replay.Step(dt)||Timer<0){replay.End();Stage=SumoStage.HeatResult;Timer=1.4f;}return;}
  if(Stage==SumoStage.HeatResult){Timer-=dt;if(Timer<=0){if(rules.Complete)EndMatch();else{rules.NextHeat();BeginHeat();}}return;}
  Clock+=dt;float target=Clock>shrinkBegins?Mathf.Max(minimumRadius,initialRadius-(Clock-shrinkBegins)*shrinkSpeed):initialRadius;if(target!=Radius){Radius=target;ring.localScale=new Vector3(Radius,1,Radius);ShrinkFrames++;}
  awards.Clear();for(int i=0;i<setup.count;i++){soundCooldown[i]=Mathf.Max(0,soundCooldown[i]-dt);if(!rules.alive[i])continue;var body=fighters[i].truck.body;var center=body.worldCenterOfMass;attribution.Observe(i,Clock,dt,center,body.linearVelocity);if(SumoRules.Outside(center.x,center.z,Radius)){int credited=attribution.TakeCredit(i,Clock,center,body.linearVelocity);rules.Crossed(i,credited);if(credited>=0){if(awards.Length>0)awards.Append(" · ");awards.Append(setup.players[credited].name).Append(" +1 RING-OUT");Pulse(credited,.3f,.12f);}fighters[i].Expression(SumoFace.Eliminated,10,4);fighters[i].SnapFace();fighters[i].truck.Power(false);body.detectCollisions=false;feedback.Play(3,0,true);Pulse(i,.6f,.2f);}}
  if(awards.Length>0){awardNotice=awards.ToString();awardUntil=Clock+2.8f;feedback.Play(5,0,true);}
  if(rules.FinishStep()){ResolveHeat();return;}if(Clock>=maximumHeat){rules.TimeoutDraw();ResolveHeat();return;}
  for(int i=0;i<setup.count;i++)if(rules.alive[i]){Vector2 input=commands[i];bool shove=actions[i];if(setup.players[i].source==BowlingSource.AI){Bot(i,dt);input=ai[i];shove=aiShove[i];}fighters[i].Tick(input,shove,dt);}replay.Record(Clock,((1<<setup.count)-1)|(1<<4));
 }
 void ResolveHeat(){if(rules.HeatWinner<0){HeatDraws++;notice=Clock>=maximumHeat?"TIME LIMIT · NO SURVIVAL BONUS":"SAME-STEP RING OUT · NO SURVIVAL BONUS";}else{fighters[rules.HeatWinner].Expression(SumoFace.Victory,10,5);fighters[rules.HeatWinner].SnapFace();notice=setup.players[rules.HeatWinner].name+" +3 SURVIVAL · WINS THE HEAT";}if(awards.Length>0)notice=awards+" · "+notice;feedback.Play(5,0,true);replay.Record(Clock+.051f,((1<<setup.count)-1)|(1<<4));foreach(var fighter in fighters){fighter.truck.Power(false);fighter.truck.body.isKinematic=true;fighter.gameObject.SetActive(false);}ring.gameObject.SetActive(false);Stage=SumoStage.Replay;Timer=0;replay.Begin(Mathf.Max(0,Clock-5));}
 void Bot(int slot,float dt){var t=fighters[slot].truck;var p=t.body.worldCenterOfMass;float radial=new Vector2(p.x,p.z).magnitude;float skill=(int)setup.players[slot].difficulty;stuck[slot]=t.body.linearVelocity.magnitude<.45f?stuck[slot]+dt:0;if(stuck[slot]>1.6f+.23f*((slot+rules.Heat)%4)){reverse[slot]=.9f;stuck[slot]=0;}reverse[slot]=Mathf.Max(0,reverse[slot]-dt);think[slot]-=dt;aiShove[slot]=false;if(think[slot]>0)return;think[slot]=Mathf.Lerp(.23f,.08f,skill*.5f);Vector3 target=Vector3.zero;bool danger=radial>Radius-Mathf.Lerp(2.1f,2.9f,skill*.5f);float distance=float.MaxValue;if(!danger)for(int i=0;i<setup.count;i++)if(i!=slot&&rules.alive[i]){var q=fighters[i].truck.body.worldCenterOfMass;float edgeOpportunity=new Vector2(q.x,q.z).magnitude/Mathf.Max(1,Radius);float leaderPressure=rules.points[i]>rules.points[slot]?1.15f:1;float value=(q-p).sqrMagnitude*(1+.08f*Mathf.Sin(slot*13+i*7+rules.Heat))/((1+edgeOpportunity*Mathf.Lerp(.15f,.7f,skill*.5f))*leaderPressure);if(value<distance){distance=value;target=q;}}var direction=target-p;direction.y=0;var forward=t.body.rotation*Vector3.forward;float angle=Vector3.SignedAngle(forward,direction,Vector3.up);float steering=Mathf.Clamp(angle/35,-1,1);float throttle=Mathf.Abs(angle)>100?-.75f:Mathf.Abs(angle)>50?.5f:1;if(throttle<0)steering=-steering;if(reverse[slot]>0){throttle=-.8f;steering=slot%2==0?.8f:-.8f;}ai[slot]=new Vector2(steering,throttle);aiShove[slot]=!danger&&direction.magnitude<4.3f&&Mathf.Abs(angle)<Mathf.Lerp(17,28,skill*.5f)&&Vector3.Dot(t.body.linearVelocity,forward)>-.5f&&fighters[slot].cooldown<=0;}
 public float RecordContact(int victim,Collision collision,bool sustained){
  if(!Live||Stage!=SumoStage.Fight||victim<0||victim>=setup.count||!rules.alive[victim]||collision.rigidbody==null)return 0;
  int attacker=-1;for(int i=0;i<setup.count;i++)if(i!=victim&&fighters[i].truck.body==collision.rigidbody){attacker=i;break;}
  Vector3 normal=Vector3.zero;float closing=0;for(int i=0;i<collision.contactCount;i++){var n=collision.GetContact(i).normal;normal+=n;closing=Mathf.Max(closing,Mathf.Abs(Vector3.Dot(collision.relativeVelocity,n)));}
  if(attacker<0||!rules.alive[attacker]||normal.sqrMagnitude<.01f)return closing;normal.Normalize();
  var direction=Vector3.ProjectOnPlane(normal,Vector3.up).normalized;var other=fighters[attacker];float incoming=Vector3.Dot(other.IncomingVelocity,direction);bool activePush=(sustained&&Mathf.Abs(other.truck.command.y)>.5f&&Vector3.Dot((other.truck.body.rotation*Vector3.forward)*Mathf.Sign(other.truck.command.y),direction)>.5f)||(other.ShovingThisStep&&Vector3.Dot(other.truck.body.rotation*Vector3.forward,direction)>.5f);
  // Raw Collision.impulse can have the same sign in both callbacks. Contact
  // normals identify the receiving direction; magnitude measures actual force.
  if(attribution.Record(victim,attacker,Clock,fighters[victim].IncomingPosition,normal,collision.impulse.magnitude*Mathf.Max(0,Vector3.Dot(normal,direction))/Mathf.Max(.001f,fighters[victim].truck.body.mass),incoming,closing,activePush)){QualifyingContacts++;LastImpactVictim=victim;LastImpactAttacker=attacker;LastReceivingNormal=normal;LastContactSpeed=closing;}
  return closing;
 }
 public void Shoved(int slot){feedback.Play(0,0,true);Pulse(slot,.3f,.1f);}
 public void Impacted(int slot,float speed){Impacts++;if(soundCooldown[slot]>0)return;soundCooldown[slot]=.25f;feedback.Play(1,0,true);Pulse(slot,Mathf.Clamp01(speed*.05f),.1f);}
 public override void ExtraAction(string key){if(Stage!=SumoStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")Timer=-1;ConsumeActions();}
 protected override void Present(float dt){if(broadcast==null)return;float radius=Stage==SumoStage.Replay?Mathf.Max(minimumRadius,replay.ghosts[4].localScale.x):Mathf.Max(minimumRadius,Radius);var offset=Stage==SumoStage.Replay&&replay.Angle==1?new Vector3(18,16,-7):Stage==SumoStage.Replay&&replay.Angle==2?new Vector3(-18,14,8):new Vector3(0,15,-26);broadcast.Pose(Vector3.up*.3f,offset,58,true);fit.arenaBounds=new Bounds(Vector3.up*.45f,new Vector3((radius+1)*2,2.5f,(radius+1)*2));fit.Apply();}
 protected override void StopGame(){replay?.End();if(fighters!=null)foreach(var fighter in fighters){fighter.truck.Power(false);fighter.truck.body.isKinematic=true;fighter.StopAudio();}}
 protected override void StopSounds(){if(fighters!=null)foreach(var fighter in fighters)if(fighter!=null)fighter.StopAudio();}
}
